def maxAverageOfPath(cost):
    N = len(cost)
    dp = [[0] * N for _ in range(N)]

    # Initialize the first row and first column
    for i in range(N):
        dp[0][i] = cost[0][i]
        dp[i][0] = cost[i][0]

    # Fill the dp table
    for i in range(1, N):
        for j in range(1, N):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + cost[i][j]

    # Calculate the maximum average
    max_avg = 0
    for i in range(N):
        for j in range(N):
            max_avg = max(max_avg, dp[i][j] / (i + j + 1))

    return max_avg
